    fun valid(index: Int) = index in colors.indices

    /** The swatch closest to [color] (pack colours are mapped onto the palette). */
    fun nearest(color: Int): Int {
        var best = 0
        var distance = Long.MAX_VALUE
        colors.forEachIndexed { i, c ->
            val dr = ((c shr 16) and 255) - ((color shr 16) and 255)
            val dg = ((c shr 8) and 255) - ((color shr 8) and 255)
            val db = (c and 255) - (color and 255)
            val d = 2L * dr * dr + 4L * dg * dg + 3L * db * db
            if (d < distance) {
                distance = d
                best = i
            }
        }
        return best
    }
